SELECT AVG(unit_price) AS gia_niem_yet_trung_binh
FROM products
WHERE is_active = 1;

SELECT SUM(o.shipping_fee) AS tong_phi_van_chuyen
FROM orders o
WHERE o.status = 1;

SELECT p.category, COUNT(p.product_id) AS so_san_pham
FROM products p
GROUP BY p.category;

SELECT SUM(oi.quantity * oi.unit_price * (1 - oi.discount / 100.0)) AS tong_doanh_thu
FROM order_items oi
JOIN orders o ON oi.order_id = o.order_id;
